// DO NOT EDIT. GENERATED BY `quilt expand --prelude // No runtime: its quotes are ⟨str⟩, template literals. print.ts.quilt`.

// Phib's printers: values, types, expressions and recipes as Phib text,
// the language syntax.js reads, written with Quilt quotes. gen.sh expands
// this into static/print.js (checked in; `just phib-quilt-check` holds them
// together), and syntax.js exports what it prints.
//
// Quilt has no grammar for Phib, so the quotes are `text`, with ↙…↘ for
// what varies and ↙←(list, sep)↘ to join. The first quote's ⟨str⟩ makes
// every quote a template literal, so the expansion needs no runtime.
// No runtime: its quotes are ⟨str⟩, template literals.

import { isTuple } from "./syntax.js";

const PREC = { "||": 1, "&&": 2, "==": 3, "!=": 3, "<": 3, "<=": 3, ">": 3, ">=": 3, mod: 4, "+": 5, "-": 5 };

// Its arguments, as written between parentheses.
const list = (xs, print) => `${((items, sep = "\n") => Array.from(items, String).join(sep))(xs.map((x) => print(x)), ", ")}`;
// In parentheses if it's held tighter than it binds.
const held = (s, tight) => (tight ? `(${s})` : s);

export function printValue(v) {
  if (v === null) return `none`;
  if (v === undefined) return `*`;
  if (typeof v === "number" || typeof v === "boolean" || typeof v === "string") return String(v);
  if (v.hole) return `*`;
  if (isTuple(v.c)) return `(${list(v.a, printValue)})`;
  return v.a.length ? `${v.c}(${list(v.a, printValue)})` : v.c;
}

// A type as written.
export function printType(ty) {
  switch (ty.k) {
    case "Nat":
      return `Nat<${ty.n}>`;
    case "Int":
      return `Int<${ty.lo}, ${ty.hi}>`;
    case "opt":
      return `${printType(ty.of)}?`;
    case "var":
      return ty.name;
    case "user":
      if (isTuple(ty.name)) return `(${list(ty.args, printType)})`;
      return ty.args?.length ? `${ty.name}<${list(ty.args, printType)}>` : ty.name;
  }
  return ty.k;
}

// Any expression, pattern or template. `ctx` is how tightly it is held:
// 0 at the top of a cell or argument, higher inside operators.
export function printExpr(e, ctx = 0) {
  switch (e.t) {
    case "any":
      return `_`;
    case "keep":
      return `*`;
    case "var":
    case "named":
      return e.n;
    case "lit":
      return printValue(e.v);
    case "layers":
      return `${((items, sep = "\n") => Array.from(items, String).join(sep))(e.items.map((a) => printExpr(a)), " / ")}`;
    case "con":
      if (isTuple(e.c)) return `(${list(e.args, printExpr)})`;
      return e.args.length ? `${e.c}(${list(e.args, printExpr)})` : e.c;
    case "call":
      return `${e.f}(${list(e.args, printExpr)})`;
    case "list":
      return `[${list(e.items, printExpr)}]`;
    case "bind":
      return `${e.n}@${printExpr(e.p, 9)}`;
    case "not":
      return `!${printExpr(e.p, 9)}`;
    case "or":
      return held(`${((items, sep = "\n") => Array.from(items, String).join(sep))(e.alts.map((a) => printExpr(a, 1)), " | ")}`, ctx > 0);
    case "upd":
      return held(`${printExpr(e.e, 9)} { ${((items, sep = "\n") => Array.from(items, String).join(sep))(e.fields.map(([f, x]) => `${f} = ${printExpr(x)}`), ", ")} }`, ctx > 8);
    case "if":
      return held(`if ${printExpr(e.c)} then ${printExpr(e.a)} else ${printExpr(e.b)}`, ctx > 0);
    case "bin": {
      const p = PREC[e.op];
      return held(`${printExpr(e.a, p)} ${e.op} ${printExpr(e.b, p + 1)}`, ctx > p);
    }
  }
  throw new Error(`can't print ${JSON.stringify(e)}`);
}

// A cell, as written.
export const printCell = (e) => printExpr(e);

// A recipe, as it would appear in a file, with its cells in columns: each
// line it has, one after another.
export function printRecipe(r, { group = true } = {}) {
  const lines = [
    group && `group ${r.group}`,
    `${r.yours ? `yours ` : ""}recipe ${r.id} ${JSON.stringify(r.name)}${r.in ? ` in ${r.in}` : ""}`,
    r.on && `  on ${printExpr(r.on)}`,
    ...rows(r),
    r.where && `  where ${printExpr(r.where)}`,
    r.chance != null && `  chance ${r.chance}%`,
    ...(r.add ?? []).map((a) => `  add ${a.reg} ${printExpr(a.e)}`),
    r.limit && `  limit ${limitWords(r.limit)}`,
  ];
  return `${((items, sep = "\n") => Array.from(items, String).join(sep))(lines.filter((l) => typeof l === "string"), "\n")}`;
}

// A recipe's Before and After, a row a line, each column as wide as its widest cell.
function rows(r) {
  const B = r.before.map((row) => row.map(printCell));
  const A = r.after.map((row) => row.map(printCell));
  const cols = r.before[0].length;
  const wb = Array.from({ length: cols }, (_, j) => Math.max(...B.map((row) => row[j].length)));
  const wa = Array.from({ length: cols }, (_, j) => Math.max(...A.map((row) => row[j].length)));
  return B.map((row, i) => {
    const left = row.map((s, j) => s.padEnd(wb[j]));
    const right = A[i].map((s, j) => (j < cols - 1 ? s.padEnd(wa[j]) : s));
    return `  ${((items, sep = "\n") => Array.from(items, String).join(sep))(left, "  ")}  ->  ${((items, sep = "\n") => Array.from(items, String).join(sep))(right, "  ")}`.trimEnd();
  });
}

// What a recipe's limit allows, in words.
function limitWords(l) {
  const words = [l.max && `max ${l.max.join("x")}`, l.noFun && `no fun`, l.noVar && `no var`, l.only && `only ${((items, sep = "\n") => Array.from(items, String).join(sep))(l.only, " ")}`];
  return `${((items, sep = "\n") => Array.from(items, String).join(sep))(words.filter(Boolean), " ")}`;
}
